### Disjointness
:Person owl:disjointWith :Band .
:Instrument owl:disjointWith :Role .
:Album owl:disjointWith :Track, :Song, :Performance .
:Track owl:disjointWith :Song .
:City owl:disjointWith :Region .
:Region owl:disjointWith :Country .

### Restrictions and Axioms
# Album must have at least one track
:Album rdfs:subClassOf [
    a owl:Restriction ;
    owl:onProperty :containsTrack ;
    owl:minQualifiedCardinality "1"^^xsd:nonNegativeInteger ;
    owl:onClass :TrackInAlbum
] .

# TrackInAlbum links to exactly one Track
:TrackInAlbum rdfs:subClassOf [
    a owl:Restriction ;
    owl:onProperty :track ;
    owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger ;
    owl:onClass :Track
] .

# All BandMembership must refer to a Person and Band
:BandMembership rdfs:subClassOf [
    a owl:Restriction ;
    owl:onProperty :memberPerson ;
    owl:allValuesFrom :Person
], [
    a owl:Restriction ;
    owl:onProperty :memberBand ;
    owl:allValuesFrom :Band
] .

# All AlbumRecording must refer to an Album and Band
:AlbumRecording rdfs:subClassOf [
    a owl:Restriction ;
    owl:onProperty :recordedAlbum ;
    owl:allValuesFrom :Album
], [
    a owl:Restriction ;
    owl:onProperty :recordedBy ;
    owl:allValuesFrom :Band
] .

# All SongComposition must refer to a Song and Person
:SongComposition rdfs:subClassOf [
    a owl:Restriction ;
    owl:onProperty :composedSong ;
    owl:allValuesFrom :Song
], [
    a owl:Restriction ;
    owl:onProperty :composedBy ;
    owl:allValuesFrom :Person
] .

# All PerformanceSong must refer to a Song and optionally a Track
:PerformanceSong rdfs:subClassOf [
    a owl:Restriction ;
    owl:onProperty :performedSong ;
    owl:allValuesFrom :Song
], [
    a owl:Restriction ;
    owl:onProperty :performedTrack ;
    owl:allValuesFrom :Track
] .

# --- GCA: CurrentBandMember equivalent class ---
:CurrentBandMember a owl:Class ;
    rdfs:label "Current Band Member" ;
    rdfs:comment "A person who is currently a member of a band (no membershipEnd date in BandMembership)." ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            :Person
            [ a owl:Restriction ;
              owl:onProperty :personMembership ;
              owl:someValuesFrom [
                a owl:Class ;
                owl:intersectionOf (
                  :BandMembership
                  [ a owl:Restriction ;
                    owl:onProperty :membershipEnd ;
                    owl:cardinality "0"^^xsd:nonNegativeInteger
                  ]
                )
              ]
            ]
        )
    ] .

